const input = $('📝 INPUT').first().json;
const cfg   = $('⚙️ CONFIG').first().json;
return [{ json: { ...input, ...cfg } }];

const params = $('🔀 Unir Params').first().json;
const tema = (params.tema || '').toLowerCase().trim();

// getAll puede retornar 0 ítems (sheet vacío) o error — ambos = sin duplicado
const rows = $input.all()
  .map(i => i.json)
  .filter(r => !r.error);

const dup = rows.find(r =>
  (r.TEMA || '').toLowerCase().trim() === tema &&
  (r.ESTADO || '') === 'M6_PROCESSED'
);

return [{ json: {
  isDuplicate: !!dup,
  existingPdfUrl: dup ? (dup.PDF_URL || '') : '',
  existingHotmart: dup ? (dup.HOTMART_LINK || '') : '',
  ...params
}}];

const p = $input.first().json;
const tipoMap = {
  checklist: 'checklist práctico con ítems accionables (listas de verificación)',
  ebook:     'ebook completo con contenido educativo por capítulos',
  guia:      'guía paso a paso con instrucciones claras',
  tutorial:  'tutorial detallado con pasos y ejercicios prácticos'
};
const tipoLabel = tipoMap[p.tipo] || 'infoproducto digital';

const sysPrompt = `Eres experto en creación de infoproductos digitales de alta conversión para el mercado hispanohablante. Generas contenido rico, práctico y profesional. RESPONDE ÚNICAMENTE CON UN OBJETO JSON VÁLIDO, sin markdown, sin bloques de código, sin texto antes ni después del JSON.`;

const userPrompt = `Crea un ${tipoLabel} completo sobre "${p.tema}" para dueños de ${p.especie}s.

REGLAS:
- Tono cálido, experto y cercano al lector
- Mínimo 8 secciones/capítulos
- Para checklists: 6-10 ítems por sección, concisos y accionables
- Para otros tipos: 200-300 palabras por sección
- La descripcion debe ser atractiva y de máx 190 caracteres sin saltos de línea

JSON ESPERADO (responde SÓLO con este JSON, sin nada más):
{
  "titulo": "título del infoproducto (máx 80 chars)",
  "subtitulo": "subtítulo que complementa y engancha",
  "descripcion": "descripción vendedora para Hotmart (máx 190 chars, una sola línea)",
  "palabras_clave": ["kw1", "kw2", "kw3", "kw4", "kw5"],
  "introduccion": "texto de introducción (2-3 párrafos separados por doble salto de línea)",
  "secciones": [
    {
      "titulo": "nombre de la sección",
      "contenido": "texto del contenido (omitir para checklists)",
      "items": ["ítem 1", "ítem 2"]
    }
  ],
  "conclusion": "texto de conclusión (1-2 párrafos)",
  "cta": "llamada a la acción urgente y específica (1-2 líneas)"
}`;

const body = JSON.stringify({
  model: 'deepseek-chat',
  temperature: 0.72,
  max_tokens: 4000,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: sysPrompt },
    { role: 'user',   content: userPrompt }
  ]
});

return [{ json: { ...p, _dsBody: body } }];

const dsResponse = $input.first().json;
const params = $('📝 Preparar Prompt DeepSeek').first().json;

const raw = dsResponse.choices?.[0]?.message?.content || dsResponse.choices?.[0]?.text || '';

let ds;
try {
  ds = JSON.parse(raw);
} catch(e) {
  // Try to extract JSON from response if wrapped
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('DeepSeek no devolvió JSON válido: ' + raw.substring(0, 200));
  ds = JSON.parse(match[0]);
}

if (!ds.titulo || !ds.secciones) {
  throw new Error('JSON incompleto de DeepSeek — faltan campos titulo o secciones');
}

return [{ json: { ...params, ds } }];

const { ds, tipo, especie, tema, precio,
        SHEET_ID, HOJA_INFOPRODUCTOS, GOOGLE_DRIVE_FOLDER_ID,
        HOTMART_CLIENT_ID, HOTMART_CLIENT_SECRET, MONEDA_HOTMART, WARRANTY_DIAS } = $input.first().json;

const primaryColor = '#1e40af';
const accentColor  = '#10b981';
const year         = new Date().getFullYear();

function esc(s) {
  return String(s || '')
    .replace(/&/g,'&amp;').replace(/</g,'&lt;')
    .replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function buildSection(s, idx) {
  const isCheck = Array.isArray(s.items) && s.items.length > 0;
  let body;
  if (isCheck) {
    const items = s.items.map(it =>
      `<div class="ci"><span class="ck">&#9744;</span><span>${esc(it)}</span></div>`
    ).join('');
    body = `<div class="checklist">${items}</div>`;
  } else {
    const paras = (s.contenido || '').split(/\n+/).filter(Boolean)
      .map(p => `<p>${esc(p)}</p>`).join('');
    body = paras || '<p></p>';
  }
  return `<div class="section"><h2>${idx}. ${esc(s.titulo)}</h2>${body}</div>`;
}

const tocItems = ds.secciones.map((s,i) =>
  `<li>${i+1}. ${esc(s.titulo)}</li>`
).join('');

const sections = ds.secciones.map((s,i) => buildSection(s, i+1)).join('');

const introParas = (ds.introduccion || '').split(/\n+/).filter(Boolean)
  .map(p => `<p>${esc(p)}</p>`).join('');

const conclParas = (ds.conclusion || '').split(/\n+/).filter(Boolean)
  .map(p => `<p>${esc(p)}</p>`).join('');

const html = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<title>${esc(ds.titulo)}</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:Georgia,'Times New Roman',serif;color:#1a1a2e;background:#fff;font-size:13pt;line-height:1.8}
.cover{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;background:linear-gradient(135deg,${primaryColor} 0%,#1e3a8a 100%);color:#fff;padding:80px 60px;text-align:center;page-break-after:always}
.cover h1{font-size:2.2em;margin-bottom:24px;line-height:1.2;max-width:700px}
.cover h2{font-size:1.2em;font-weight:300;opacity:.88;margin-bottom:48px;max-width:600px}
.cover .badge{background:rgba(255,255,255,.15);border:2px solid rgba(255,255,255,.4);border-radius:30px;padding:10px 30px;font-size:.85em;letter-spacing:3px;text-transform:uppercase}
.toc{padding:70px 100px;page-break-after:always}
.toc h2{font-size:1.7em;color:${primaryColor};border-bottom:3px solid ${primaryColor};padding-bottom:14px;margin-bottom:32px}
.toc ol{list-style:none}
.toc li{padding:9px 0;border-bottom:1px dotted #d1d5db;font-size:1em}
.intro{padding:60px 100px;page-break-after:always}
.intro h2{font-size:1.6em;color:${primaryColor};margin-bottom:22px}
.intro p{margin-bottom:16px}
.section{padding:50px 100px;page-break-after:always}
.section h2{font-size:1.5em;color:${primaryColor};border-left:5px solid ${accentColor};padding-left:18px;margin-bottom:28px}
.section p{margin-bottom:16px}
.checklist{margin-top:8px}
.ci{display:flex;align-items:flex-start;gap:14px;padding:12px 16px;margin-bottom:9px;border:1px solid #e5e7eb;border-radius:8px;background:#f9fafb}
.ck{font-size:1.2em;color:${primaryColor};flex-shrink:0;margin-top:1px}
.concl{padding:50px 100px;page-break-after:always}
.concl h2{font-size:1.5em;color:${primaryColor};margin-bottom:20px}
.concl p{margin-bottom:16px}
.cta-box{margin:40px 100px 60px;padding:50px 60px;background:${primaryColor};color:#fff;border-radius:16px;text-align:center;page-break-inside:avoid}
.cta-box h3{font-size:1.6em;margin-bottom:18px}
.cta-box p{font-size:1.1em;opacity:.9;line-height:1.6}
.footer{text-align:center;padding:30px;font-size:.8em;color:#9ca3af;border-top:1px solid #e5e7eb}
</style>
</head>
<body>
<div class="cover">
  <h1>${esc(ds.titulo)}</h1>
  <h2>${esc(ds.subtitulo)}</h2>
  <div class="badge">${esc(tipo.toUpperCase())} DIGITAL &nbsp;|&nbsp; ${esc(especie.toUpperCase())}</div>
</div>
<div class="toc">
  <h2>&#128203; Tabla de Contenidos</h2>
  <ol>${tocItems}</ol>
</div>
<div class="intro">
  <h2>Introducción</h2>
  ${introParas}
</div>
${sections}
<div class="concl">
  <h2>Conclusión</h2>
  ${conclParas}
</div>
<div class="cta-box">
  <h3>&#128640; ¡Es Momento de Actuar!</h3>
  <p>${esc(ds.cta)}</p>
</div>
<div class="footer">${esc(ds.titulo)} &copy; ${year} &nbsp;|&nbsp; Todos los derechos reservados<!-- M6_PROCESSED --></div>
</body>
</html>`;

return [{ json: {
  ds, tipo, especie, tema, precio,
  htmlContent: html,
  SHEET_ID, HOJA_INFOPRODUCTOS, GOOGLE_DRIVE_FOLDER_ID,
  HOTMART_CLIENT_ID, HOTMART_CLIENT_SECRET, MONEDA_HOTMART, WARRANTY_DIAS
}}];

const data = $input.first().json;
const BOUNDARY = 'M6_bnd_' + Date.now();

const meta = { name: '[M6] ' + data.ds.titulo, mimeType: 'application/vnd.google-apps.document' };
if (data.GOOGLE_DRIVE_FOLDER_ID) meta.parents = [data.GOOGLE_DRIVE_FOLDER_ID];
const metaStr = JSON.stringify(meta);

// Multipart/related body (RFC 2046)
// HTML encoded as base64 to avoid n8n expression collisions
const htmlB64 = Buffer.from(data.htmlContent, 'utf8').toString('base64');

const uploadBody = [
  '--' + BOUNDARY,
  'Content-Type: application/json; charset=UTF-8',
  '',
  metaStr,
  '--' + BOUNDARY,
  'Content-Type: text/html; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
  '',
  htmlB64,
  '--' + BOUNDARY + '--'
].join('\r\n');

return [{ json: {
  ...data,
  _uploadBody:   uploadBody,
  _contentType:  'multipart/related; boundary="' + BOUNDARY + '"'
}}];

// $json here is the Drive permissions response; read upstream nodes by name
const params  = $('📦 Preparar Upload a Drive').first().json;
const docResp = $('☁️ Crear Google Doc (Drive API)').first().json;

const gdocId  = docResp.id;
const pdfUrl  = `https://docs.google.com/document/d/${gdocId}/export?format=pdf`;
const docLink = `https://docs.google.com/document/d/${gdocId}/view`;

return [{ json: {
  ...params,
  gdocId, pdfUrl, docLink,
  rowData: {
    TIMESTAMP:  new Date().toISOString(),
    TEMA:       params.tema,
    TITULO:     params.ds.titulo,
    ESPECIE:    params.especie,
    TIPO:       params.tipo,
    PRECIO:     params.precio,
    ESTADO:     'M6_PROCESSED',
    GDOC_ID:    gdocId,
    PDF_URL:    pdfUrl,
    HOTMART_ID: '',
    HOTMART_LINK: ''
  }
}}];
